/* Sign-up form · style.css */

/* Step 4: the page and the card */
* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 24px 16px;
  font-family: Arial, sans-serif;
  color: #1e1527;
  background: linear-gradient(135deg, #602b7a, #2b1640);
}

.form-box {
  width: 100%;
  max-width: 400px;
  padding: 32px 28px;
  border-radius: 16px;
  background-color: #ffffff;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.3);
}

h1 {
  margin: 0 0 24px;
  color: #43235f;
  font-size: 26px;
  text-align: center;
}

/* Step 5: the fields and the button */
.field input {
  width: 100%;
  padding: 14px 12px;
  border: 2px solid #cfc8d8;
  border-radius: 8px;
  font-size: 16px;
}

.field input:focus {
  border-color: #602b7a;
  outline: 3px solid #e3d3ee;
}

.terms {
  margin: 8px 0 16px;
  font-size: 14px;
}

.terms input {
  width: 18px;
  height: 18px;
  margin: 0 6px 0 0;
  vertical-align: middle;
}

button {
  width: 100%;
  padding: 14px;
  border: none;
  border-radius: 999px;
  background-color: #602b7a;
  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  cursor: pointer;
}

button:hover {
  background-color: #43235f;
}

/* Step 6: labels that float up (the animation) */
.field {
  position: relative;
  margin-bottom: 14px;
}

.field label {
  position: absolute;
  top: 15px;
  left: 10px;
  padding: 0 4px;
  background-color: #ffffff;
  color: #6b6177;
  transition: 0.3s;
}

.field input:focus ~ label,
.field input:not(:placeholder-shown) ~ label {
  top: -9px;
  font-size: 12px;
  color: #602b7a;
}

/* Step 7: error messages and the success message */
.error {
  min-height: 18px;
  margin: 4px 0 0;
  color: #c62828;
  font-size: 13px;
}

.field input[aria-invalid="true"] {
  border-color: #c62828;
}

.success {
  margin: 16px 0 0;
  color: #2e7d32;
  font-weight: bold;
  text-align: center;
}

