// Sign-up form · script.js

// Step 8: select the form and its fields
const form = document.querySelector("#signup-form");
const usernameInput = document.querySelector("#username");
const emailInput = document.querySelector("#email");
const passwordInput = document.querySelector("#password");
const confirmInput = document.querySelector("#confirm");
const termsInput = document.querySelector("#terms");
const success = document.querySelector("#success");

// Step 9: show or clear the error of a field
function showError(input, message) {
  const error = document.querySelector("#" + input.id + "-error");
  error.textContent = message;
  input.setAttribute("aria-invalid", "true");
}

function clearError(input) {
  const error = document.querySelector("#" + input.id + "-error");
  error.textContent = "";
  input.removeAttribute("aria-invalid");
}

function checkUsername() {
  const username = usernameInput.value.trim();
  if (username.length < 3) {
    showError(usernameInput, "Your username needs at least 3 characters.");
    return false;
  }
  clearError(usernameInput);
  return true;
}

// Step 10: the email needs an @ and a dot
function checkEmail() {
  const email = emailInput.value.trim();
  if (!email.includes("@") || !email.includes(".")) {
    showError(emailInput, "Write a valid email, like ana@mail.com.");
    return false;
  }
  clearError(emailInput);
  return true;
}

// Step 11: a safe password, written twice
function hasNumber(text) {
  for (const char of text) {
    if (char >= "0" && char <= "9") {
      return true;
    }
  }
  return false;
}

function checkPassword() {
  const password = passwordInput.value;
  if (password.length < 8 || !hasNumber(password)) {
    showError(passwordInput, "Use at least 8 characters and 1 number.");
    return false;
  }
  clearError(passwordInput);
  return true;
}

function checkConfirm() {
  if (confirmInput.value === "") {
    showError(confirmInput, "Write your password again.");
    return false;
  }
  if (confirmInput.value !== passwordInput.value) {
    showError(confirmInput, "The passwords don't match.");
    return false;
  }
  clearError(confirmInput);
  return true;
}

// Step 12: the terms box and the success message
function checkTerms() {
  if (!termsInput.checked) {
    showError(termsInput, "Accept the terms to continue.");
    return false;
  }
  clearError(termsInput);
  return true;
}

// Step 8: check the form when it's sent, without reloading the page
form.addEventListener("submit", (event) => {
  event.preventDefault();
  console.log("Checking the form...");

  // Step 12: call every check first, so all the errors appear at once
  const usernameOk = checkUsername();
  const emailOk = checkEmail();
  const passwordOk = checkPassword();
  const confirmOk = checkConfirm();
  const termsOk = checkTerms();

  if (usernameOk && emailOk && passwordOk && confirmOk && termsOk) {
    success.textContent = `Welcome, ${usernameInput.value.trim()}! Your account is ready.`;
    form.reset();
  } else {
    success.textContent = "";
  }
});
